import math

def solution_score(step_probs, how="product"):
    if how == "product":
        return math.prod(step_probs)
    if how == "min":
        return min(step_probs)
    if how == "last":
        return step_probs[-1]
    raise ValueError(how)

print(round(solution_score([0.95, 0.90, 0.92]), 3))   # 0.787
print(round(solution_score([0.97] * 8), 3))           # 0.784
print(solution_score([0.96, 0.94, 0.20, 0.90], "min"))  # 0.2
